#!/bin/bash
# Generated by dock-local: creates the topics referenced by the project (idempotent).
set -euo pipefail
BOOTSTRAP="kafka:29092"
TOPICS=(
{{#each resources.topics}}
  "{{this}}"
{{/each}}
)
if [ ${#TOPICS[@]} -eq 0 ]; then
  echo "[dock] no topics detected; auto-create is enabled on the broker."
  exit 0
fi
for t in "${TOPICS[@]}"; do
  /opt/kafka/bin/kafka-topics.sh --bootstrap-server "$BOOTSTRAP" --create --if-not-exists \
    --topic "$t" --partitions 3 --replication-factor 1 >/dev/null && echo "[dock] topic ready: $t"
done
